INSERT INTO public.source (id, title, source_type, author, edition, url, note)
SELECT id, title, source_type, author, edition, url, note FROM jsonb_populate_recordset(NULL::public.source, '[{"title": "旧五代史·卷112·太祖本纪三·广顺二年六月", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/96fe3506d094c8545f18034b0950674072209b89/content/books/zizhi-tongjian/vol-290/year-0952/part-04/sources/library/jiuwudaishi-112-june-952/source.txt", "note": "《旧五代史》卷112·太祖本纪三·广顺二年六月，段落 jiu-wudaishi-205deb4a7860-p002674；已核上下文及传主，纸本及异文待核。", "id": "66a07685-6e03-596f-8c63-d1c071b44c71"}, {"title": "宋史·卷253·列传十二·冯继业传·父兄与继任", "source_type": "primary", "author": "脱脱等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/96fe3506d094c8545f18034b0950674072209b89/content/books/zizhi-tongjian/vol-290/year-0952/part-04/sources/library/songshi-253-feng-jiye/source.txt", "note": "《宋史》卷253·列传十二·冯继业传·父兄与继任，段落 songshi-9c6e46fee832-p057409；已核上下文及传主，纸本及异文待核。", "id": "964d764e-d9ab-5995-9e02-2326398abd47"}, {"title": "宋史·卷484·列传二百四十三·周三臣·李重进传", "source_type": "primary", "author": "脱脱等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/96fe3506d094c8545f18034b0950674072209b89/content/books/zizhi-tongjian/vol-290/year-0952/part-04/sources/library/songshi-484-li-chongjin/source.txt", "note": "《宋史》卷484·列传二百四十三·周三臣·李重进传，段落 songshi-9c6e46fee832-p075287；已核上下文及传主，纸本及异文待核。", "id": "ab15acda-1e99-5717-8408-e0b638ed3ff1"}, {"title": "资治通鉴·卷290·广顺二年·六月至八月及相邻追述", "source_type": "primary", "author": "司马光等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/96fe3506d094c8545f18034b0950674072209b89/content/books/zizhi-tongjian/vol-290/year-0952/part-04/sources/library/tongjian-290-952-june-july/source.txt", "note": "《资治通鉴》卷290·广顺二年·六月至八月及相邻追述，段落 zizhi-tongjian-a63549944a71-p003452；已核上下文及传主，纸本及异文待核。", "id": "dd57516b-b590-5d31-a620-b6481f7c8700"}, {"title": "资治通鉴·卷290·广顺二年·四五月亲征兖州及相邻记事", "source_type": "primary", "author": "司马光等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/a94812079efe6f0dad4431d10d0651494739b7f1/content/books/zizhi-tongjian/vol-290/year-0952/part-03/sources/library/tongjian-290-952-april-may/source.txt", "note": "《资治通鉴》卷290·广顺二年·四五月亲征兖州及相邻记事，段落 zizhi-tongjian-a63549944a71-p003451；已核上下文及传主，纸本及异文待核。", "id": "ffdbdd7d-f017-517a-b258-cdea40188bd0"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.person (id, name, aliases, era, birth_year, death_year, description, biography, status)
SELECT id, name, aliases, era, birth_year, death_year, description, biography, status FROM jsonb_populate_recordset(NULL::public.person, '[{"name": "郭威", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷272同光元年条所见人物：郭威。", "biography": null, "status": "draft", "id": "3fe84db3-aa25-5be9-9dd3-8b46e28213af"}, {"name": "孔仁玉", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《旧五代史》称孔子第四十三代孙、前曲阜令、袭文宣公。952年郭威访孔颜后裔时，获赐绯服、任曲阜令。生卒年未载。", "biography": null, "status": "draft", "id": "b5ff2453-2610-5cb7-9e6c-7ae0460e41a7"}, {"name": "颜涉", "aliases": ["顏涉"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "颜渊后裔，《旧五代史》称乡贡三礼。952年郭威访孔颜后裔时，获任曲阜主簿。未把后裔误作直接孙子，生卒年未载。", "biography": null, "status": "draft", "id": "1284532d-fe53-58d0-a682-9502ce5e22c2"}, {"name": "吴氏（吴越顺德太夫人）", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": 952, "description": "吴越顺德太夫人。952年六月乙未去世。本段未明示丈夫、子女，与已录钱传瓘妾、钱弘俶之母吴氏是否同一人，尚待封谥等补证，暂不合并。", "biography": null, "status": "draft", "id": "6036f7d5-2eee-5210-a176-357479a149bf"}, {"name": "冯晖", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷263天复二年条所见人物：冯晖。", "biography": null, "status": "draft", "id": "e59e2b00-2873-5968-ab4c-938628164ecf"}, {"name": "冯继业", "aliases": ["馮繼業"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "大名人，字嗣宗，冯晖之子、冯继勋的弟弟。952年父亲去世前后杀兄，自掌朔方军府，六月获后周授朔方留后。《宋史》安排谋杀在父病时，时序独立保留。生卒年未录全。", "biography": null, "status": "draft", "id": "a653d65a-339b-5df1-99c3-a27f7671128d"}, {"name": "冯继勋", "aliases": ["馮繼勳"], "era": "五代十国", "birth_year": null, "death_year": 952, "description": "冯继业的兄长。952年朔方军继任过程中被冯继业杀害。出生年和此前官职未载。", "biography": null, "status": "draft", "id": "01c0e674-d51b-580b-93b3-510c2cbacdaf"}, {"name": "李澣", "aliases": ["李浣"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "李涛的弟弟，后晋翰林学士。《资治通鉴》说他多次酒后失当，石敬瑭不喜欢他；940年九月翰林学士职务被撤销、事务归中书舍人。《旧五代史》同期学士名写李浣，另记他调吏部员外郎，保留字形说明。生卒年未载。", "biography": null, "status": "draft", "id": "cc1a8d2a-5333-5d3b-befa-dea7a7c759a6"}, {"name": "萧海真", "aliases": ["蕭海真", "萧海贞", "蕭海貞"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "契丹幽州节度使，耶律阮的妻弟，与李澣交好。952年答允李澣的内附劝说，《旧五代史》同日表述称萧海贞，按同官同使者对应。生卒年未载。", "biography": null, "status": "draft", "id": "c06c21a8-c9c1-5550-8ed7-fdbef7e6e700"}, {"name": "李涛", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷257光启三年条所见人物：李涛。", "biography": null, "status": "draft", "id": "6d85380a-8ee9-587e-a411-db6354d07b6d"}, {"name": "耶律阮", "aliases": ["耶律兀欲", "兀欲", "永康王"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "小字兀欲，东丹王耶律倍之子。《资治通鉴》947年条下称永康王，记耶律德光将李彦绅、秦继旻的家属和财产交给他。《辽史》卷五明确名阮、小字兀欲，按同一主体建档；王号具体授封时间仍须另据后文校核，生卒年暂未录。", "biography": null, "status": "draft", "id": "42a17de5-aa28-50e6-bab8-b134f0113f3f"}, {"name": "田重霸", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "定州谍者。952年受李澣委托递交绢表，六月壬寅到大梁。生卒年未载。", "biography": null, "status": "draft", "id": "a08e861c-c65a-50fd-a664-d58dc45726f9"}, {"name": "王峻", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "安阳人，刘知远的客将。947年奉三表赴契丹，报告贺入大梁、暂不离太原及贡路受阻。《旧五代史》称牙将王峻，记二月出使和携杖回太原。生卒年本段未核。", "biography": null, "status": "draft", "id": "196d9879-50e7-5ff5-9d99-4879fa1ea3a2"}, {"name": "郑仁诲", "aliases": ["鄭仁誨"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "晋阳人，后周内客省使、恩州团练使。952年三月任枢密副使，新旧五代史同日记载。生卒年尚未录入。", "biography": null, "status": "draft", "id": "f7eb66ac-1c5c-5720-aa2e-9256e75c2b71"}, {"name": "向训", "aliases": ["向訓"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后周军官。951年与陈思让参与虒亭战事，《旧五代史》称监军，《宋史》称都监。生卒年及后续改名尚未据本次引文录入。", "biography": null, "status": "draft", "id": "1d29bcb9-6ec9-5369-89ff-ea67f0460acc"}, {"name": "李重进", "aliases": ["李重進"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "沧州人，福庆长公主之子，郭威的外甥，生于太原。郭威在藩镇时期的将佐，952年任恩州团练使，逐渐受重用。《宋史》还记当年内殿职务变化，具体任日未载。生卒年尚未录入。", "biography": null, "status": "draft", "id": "9769d0fb-1d80-593e-9aa3-e4c22416f835"}, {"name": "陈观", "aliases": ["陳觀"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后汉给事中。947年十月刘知远亲征邺都时，派他入城向杜重威宣谕归降，杜重威闭门拒绝。生卒年未载。", "biography": null, "status": "draft", "id": "91fa9e7e-dc34-57a5-9199-5fe3f6f5ed8f"}, {"name": "福庆长公主（郭威妹）", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "郭威的妹妹、李重进的母亲。福庆为封号，原文未给个人名字及生卒年。", "biography": null, "status": "draft", "id": "9351d90a-840f-595e-ad05-5bc4b9300298"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.event (id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status)
