INSERT INTO public.fact_claim (id, subject_table, subject_id, field_path, claim_text, source_id, citation, note, status)
SELECT id, subject_table, subject_id, field_path, claim_text, source_id, citation, note, status FROM jsonb_populate_recordset(NULL::public.fact_claim, '[{"subject_table": "event", "field_path": "description", "claim_text": "郭威到曲阜祭孔，认为孔子为帝王之师，行拜礼。", "citation": "卷290·广顺二年（952年六月至七月及相邻追述）·zztj-v290-y0952-p025·原文件第114行", "note": "原文：六月，乙酉朔，帝如曲阜，谒孔子祠。既尊，将拜。左右曰：“孔子，陪臣也，不当以天子拜之。”帝曰：“孔子百世帝王之师，敢不敬乎！”遂拜之。；核对说明：陪臣与帝王师为礼制争论中的说法；底本既尊疑奠字，按祭祀语境解释，摘录不改。", "status": "draft", "id": "d1d044de-de42-5d6d-ba0e-46c802708f1b", "subject_id": "b4b95821-2da1-5966-baad-14edba19edf7", "source_id": "ffdbdd7d-f017-517a-b258-cdea40188bd0"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "952年六月乙酉朔", "citation": "卷290·广顺二年（952年六月至七月及相邻追述）·zztj-v290-y0952-p025·原文件第114行", "note": "原文：六月，乙酉朔，帝如曲阜，谒孔子祠。既尊，将拜。左右曰：“孔子，陪臣也，不当以天子拜之。”帝曰：“孔子百世帝王之师，敢不敬乎！”遂拜之。；核对说明：按《资治通鉴》及对应补证纪时；追叙或他书记载另作说明，不自行换算公历日期。", "status": "draft", "id": "85f37f5e-54ca-59a3-be24-f6c34893f655", "subject_id": "b4b95821-2da1-5966-baad-14edba19edf7", "source_id": "ffdbdd7d-f017-517a-b258-cdea40188bd0"}, {"subject_table": "person", "field_path": "description", "claim_text": "郭威：到曲阜谒孔子祠，反对不拜建议并行拜礼。", "citation": "卷290·广顺二年（952年六月至七月及相邻追述）·zztj-v290-y0952-p025·原文件第114行", "note": "原文：六月，乙酉朔，帝如曲阜，谒孔子祠。既尊，将拜。左右曰：“孔子，陪臣也，不当以天子拜之。”帝曰：“孔子百世帝王之师，敢不敬乎！”遂拜之。；核对说明：核对同名、职务及行动后识别主体；展示简体，摘录保留原字。", "status": "draft", "id": "4cf38f56-d164-52f2-b95c-006efe5d6425", "subject_id": "3fe84db3-aa25-5be9-9dd3-8b46e28213af", "source_id": "ffdbdd7d-f017-517a-b258-cdea40188bd0"}, {"subject_table": "person_event", "field_path": "role", "claim_text": "郭威：到曲阜谒孔子祠，反对不拜建议并行拜礼。", "citation": "卷290·广顺二年（952年六月至七月及相邻追述）·zztj-v290-y0952-p025·原文件第114行", "note": "原文：六月，乙酉朔，帝如曲阜，谒孔子祠。既尊，将拜。左右曰：“孔子，陪臣也，不当以天子拜之。”帝曰：“孔子百世帝王之师，敢不敬乎！”遂拜之。；核对说明：参与身份依据本句；人名沿用已有主体，原文不改字。", "status": "draft", "id": "dbb92955-c31d-5c36-b51f-428e1094dec9", "subject_id": "e2479cbd-c8c4-5dd9-883e-e172f4895d6a", "source_id": "ffdbdd7d-f017-517a-b258-cdea40188bd0"}, {"subject_table": "event", "field_path": "description", "claim_text": "《旧五代史》同日记到曲阜谒祠，祭奠后欲行拜礼。", "citation": "《旧五代史》卷112·太祖本纪三·广顺二年六月，段落 jiu-wudaishi-205deb4a7860-p002674；已核上下文及传主，纸本及异文待核。", "note": "原文：六月乙酉朔，帝幸曲阜縣，謁孔子祠。既奠，將致拜，；核对说明：既奠与《资治通鉴》既尊字形差异保留，未悄改底本。", "status": "draft", "id": "e333fe3f-8c2d-585d-980a-44f467facd36", "subject_id": "b4b95821-2da1-5966-baad-14edba19edf7", "source_id": "66a07685-6e03-596f-8c63-d1c071b44c71"}, {"subject_table": "event", "field_path": "description", "claim_text": "《旧五代史》补记祭奠的酒器、银炉留在祠内。", "citation": "《旧五代史》卷112·太祖本纪三·广顺二年六月，段落 jiu-wudaishi-205deb4a7860-p002674；已核上下文及传主，纸本及异文待核。", "note": "原文：其所奠酒器、銀爐並留於祠所。；核对说明：为祭祀物品处置的补充，未编数量、价格。", "status": "draft", "id": "94106729-af01-5e11-868d-8d952fad6106", "subject_id": "b4b95821-2da1-5966-baad-14edba19edf7", "source_id": "66a07685-6e03-596f-8c63-d1c071b44c71"}, {"subject_table": "event", "field_path": "description", "claim_text": "郭威拜孔子墓，命修祠并禁止孔林砍柴采集。", "citation": "卷290·广顺二年（952年六月至七月及相邻追述）·zztj-v290-y0952-p025·原文件第114行", "note": "原文：又拜孔子墓，命葺孔子祠，禁孔林樵采。；核对说明：按原文动作分录；不外推原因与结果。", "status": "draft", "id": "c2170970-b802-5dba-9910-99deabe75fa0", "subject_id": "fced2953-2379-5658-a470-cd615b3a5f9c", "source_id": "ffdbdd7d-f017-517a-b258-cdea40188bd0"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "952年六月乙酉朔", "citation": "卷290·广顺二年（952年六月至七月及相邻追述）·zztj-v290-y0952-p025·原文件第114行", "note": "原文：又拜孔子墓，命葺孔子祠，禁孔林樵采。；核对说明：按《资治通鉴》及对应补证纪时；追叙或他书记载另作说明，不自行换算公历日期。", "status": "draft", "id": "334a039f-7bc7-550c-be60-e536c88f4283", "subject_id": "fced2953-2379-5658-a470-cd615b3a5f9c", "source_id": "ffdbdd7d-f017-517a-b258-cdea40188bd0"}, {"subject_table": "person_event", "field_path": "role", "claim_text": "郭威：拜墓，命修葺祠宇、保护孔林。", "citation": "卷290·广顺二年（952年六月至七月及相邻追述）·zztj-v290-y0952-p025·原文件第114行", "note": "原文：又拜孔子墓，命葺孔子祠，禁孔林樵采。；核对说明：参与身份依据本句；人名沿用已有主体，原文不改字。", "status": "draft", "id": "b9408b76-1cdd-5806-ad2a-77ebc2a4e8d7", "subject_id": "86bb8454-a88f-527c-8ecf-e4175aa3e597", "source_id": "ffdbdd7d-f017