aft", "id": "ba572d1a-dbb7-531d-b9a6-ca3e96cfdd52", "subject_id": "6d85380a-8ee9-587e-a411-db6354d07b6d", "source_id": "ffdbdd7d-f017-517a-b258-cdea40188bd0"}, {"subject_table": "person_relationship", "field_path": "description", "claim_text": "李涛是李澣的兄长。", "citation": "卷290·广顺二年（952年六月至七月及相邻追述）·zztj-v290-y0952-p030·原文件第119行", "note": "原文：太子宾客李涛之弟澣，在契丹为勤政殿学士，；核对说明：之弟明示长幼，沿已有同一李澣、李涛主体，旧职改变不另建人。", "status": "draft", "id": "aadf1996-a586-5ed0-80f8-4e43c561d3eb", "subject_id": "dc0e6e8e-a394-59cf-992c-5ad5600d14c3", "source_id": "ffdbdd7d-f017-517a-b258-cdea40188bd0"}, {"subject_table": "person", "field_path": "description", "claim_text": "耶律阮：史书记萧海真是耶律阮的妻弟。", "citation": "卷290·广顺二年（952年六月至七月及相邻追述）·zztj-v290-y0952-p030·原文件第119行", "note": "原文：海真，契丹主兀欲之妻弟也。；核对说明：核对同名、职务及行动后识别主体；展示简体，摘录保留原字。", "status": "draft", "id": "f8971b64-8340-5bff-b59f-aa69ff0ff9d6", "subject_id": "42a17de5-aa28-50e6-bab8-b134f0113f3f", "source_id": "ffdbdd7d-f017-517a-b258-cdea40188bd0"}, {"subject_table": "person_relationship", "field_path": "description", "claim_text": "萧海真是耶律阮的妻弟。", "citation": "卷290·广顺二年（952年六月至七月及相邻追述）·zztj-v290-y0952-p030·原文件第119行", "note": "原文：海真，契丹主兀欲之妻弟也。；核对说明：兀欲为已故耶律阮，方向表示萧海真是耶律阮的妻弟，不把当前耶律璟当此妻的丈夫。", "status": "draft", "id": "58cf791b-4bbb-562b-9212-9001e006945e", "subject_id": "35a0505c-f16c-586c-9475-795dc75a4920", "source_id": "ffdbdd7d-f017-517a-b258-cdea40188bd0"}, {"subject_table": "event", "field_path": "description", "claim_text": "李澣劝萧海真内附，萧海真答允。", "citation": "卷290·广顺二年（952年六月至七月及相邻追述）·zztj-v290-y0952-p030·原文件第119行", "note": "原文：浣说海南内附，海真欣然许之。；核对说明：底本海南按上下文指海真，疑字保持原文，不误作海南地名；答允不等于幽州已交给后周。", "status": "draft", "id": "77e655ce-75aa-5faf-ae1c-81dcba131e27", "subject_id": "3fcf3c3c-8641-5c56-9911-8787dc96811b", "source_id": "ffdbdd7d-f017-517a-b258-cdea40188bd0"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "952年六月壬寅田重霸到大梁以前", "citation": "卷290·广顺二年（952年六月至七月及相邻追述）·zztj-v290-y0952-p030·原文件第119行", "note": "原文：浣说海南内附，海真欣然许之。；核对说明：按《资治通鉴》及对应补证纪时；追叙或他书记载另作说明，不自行换算公历日期。", "status": "draft", "id": "d50c1443-3469-5328-8f70-a8483bb1676f", "subject_id": "3fcf3c3c-8641-5c56-9911-8787dc96811b", "source_id": "ffdbdd7d-f017-517a-b258-cdea40188bd0"}, {"subject_table": "person_event", "field_path": "role", "claim_text": "李澣：劝萧海真内附后周。", "citation": "卷290·广顺二年（952年六月至七月及相邻追述）·zztj-v290-y0952-p030·原文件第119行", "note": "原文：浣说海南内附，海真欣然许之。；核对说明：参与身份依据本句；人名沿用已有主体，原文不改字。", "status": "draft", "id": "10805a2b-7152-5852-b4f2-f2561783feb3", "subject_id": "42fca8f4-c228-53be-acf6-c5cf2e6e11a2", "source_id": "ffdbdd7d-f017-517a-b258-cdea40188bd0"}, {"subject_table": "person_event", "field_path": "role", "claim_text": "萧海真：答允内附劝说。", "citation": "卷290·广顺二年（952年六月至七月及相邻追述）·zztj-v290-y0952-p030·原文件第119行", "note": "原文：浣说海南内附，海真欣然许之。；核对说明：参与身份依据本句；人名沿用已有主体，原文不改字。", "status": "draft", "id": "d2023d41-f4aa-5eed-ae92-9f2efb486a5e", "subject_id": "0e047b90-98e3-5fbb-ba36-f23f6c9dcb8b", "source_id": "ffdbdd7d-f017-517a-b258-cdea40188bd0"}, {"subject_table": "event", "field_path": "description", "claim_text": "李澣让田重霸递绢表，并写信向李涛说明契丹形势。", "citation": "卷290·广顺二年（952年六月至七月及相邻追述）·zztj-v290-y0952-p030·原文件第119行", "note": "原文：澣因定州谍者田重霸赍绢表以闻，且与涛书，言：“契丹主童騃，专事宴游，无远志，非前人之比，朝廷若能用兵，必克；不然，与和，必得。二者皆利于速，度其情势，他日终不能力助河东者也。”；核对说明：童騃、无远志及不能助河东为李澣的判断，不能视为已证实的全部契丹国力；此处所说现君为耶律璟。", "status": "draft", "id": "6b117dad-c081-5e03-8103-88413df12578", "subject_id": "bffd8a81-25a4-546f-b599-06180907eb0b", "source_id": "ffdbdd7d-f017-517a-b258-cdea40188bd0"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "952年六月壬寅以前", "citation": "卷290·广顺二年（952年六月至七月及相邻追述）·zztj-v290-y0952-p030·原文件第119行", "note": "原文：澣因定州谍者田重霸赍绢表以闻，且与涛书，言：“契丹主童騃，专事宴游，无远志，非前人之比，朝廷若能用兵，必克；不然，与和，必得。二者皆利于速，度其情势，他日终不能力助河东者也。”；核对说明：按《资治通鉴》及对应补证纪时；追叙或他书记载另作说明，不自行换算公历日期。", "status": "draft", "id": "00df93f7-cac9-56ee-af8d-2d35da40985e", "subject_id": "bffd8a81-25a4-546f-b599-06180907eb0b", "source_id": "ffdbdd7d-f017-517a-b258-cdea40188bd0"}, {"subject_table": "person_event", "field_path": "ro